    lib.element.Player.prototype.searchChargeSk = function (targetSkill) {
        if (get.itemtype(this) != 'player') return -1;
        var theSkill = null,
            theLimit = Infinity;
        switch (typeof targetSkill) {
            case 'string':
                theSkill = targetSkill;
                break;
            case 'function':
                theSkill = targetSkill(this);
                break;
            default:
                return -1;
        }
        var ifo = get.info(theSkill);
        if (ifo && ifo != undefined) {
            switch (typeof ifo.chargeNeedSk) {
                case 'number':
                    theLimit = ifo.chargeNeedSk;
                    break;
                case 'function':
                    theLimit = ifo.chargeNeedSk(this);
                    break;
                default:
                    break;
            }
        }
        if (typeof theLimit != 'number') theLimit = Infinity;
        if (theLimit < 1) theLimit = 1;
        if (typeof this.storage['chargeSk_' + theSkill] != 'number') return -1;
        if (this.storage['chargeSk_' + theSkill] < 0) return -1;
        if (this.storage['chargeSk_' + theSkill] >= theLimit) return theLimit;
        return this.storage['chargeSk_' + theSkill];
    };
