    lib.element.Player.prototype.searchComboSk = function (num) {
        if (!num) num = 1;
        var theModified = num;
        for (var i of this.getSkills()) {
            var ifo = get.info(i);
            if (!ifo) continue;
            switch (typeof ifo.comboAddSk) {
                case 'number':
                    theModified += ifo.comboAddSk;
                    break;
                case 'function':
                    var theValue = ifo.comboAddSk(player);
                    switch (typeof theValue) {
                        case 'number':
                            theModified += theValue;
                            break;
                        case 'boolean':
                            if (theValue === false) return 1;
                            break;
                        default:
                            break;
                    }
                    break;
                case 'boolean':
                    if (ifo.comboAddSk === false) return 1;
                    break;
                default:
                    break;
            }
        }
        return Math.max(theModified, 1);
    };
    lib.element.Player.prototype.popupWithVideo = function (...args) {
        var list = [];
        for (var i of args) {
            list.push(i);
        }
        this.popup.apply(this, list);
        game.addVideo('popupSoulKnight', this, list);
    };
    lib.element.Player.prototype.updateMarksForSk = function (connect) {
        var list = [],
            listV = [];
        if (Array.isArray(connect)) {
            for (var i of connect) {
                var str = '';
                if (typeof i == 'string') str = i;
                else if (i && i.toString) str = i.toString();
                list.push(str);
                listV.push(this.storage[str]);
            }
        }
        if (typeof connect == 'string') {
            list.push(connect);
            listV.push(this.storage[connect]);
        }
        if (_status.connectMode && !game.online) {
            game.broadcast(
                function (player, storages, skills) {
                    for (var j = 0; j < skills.length && j < storages.length; j++) {
                        player.storage[skills[j]] = storages[j];
                    }
                },
                this,
                listV,
                list
            );
        }
        for (var i in this.marks) {
            this.updateMark(i);
        }
    };
