                    if (skill.includes('tiansuan2_4')) return true;
                    if (skill.includes('jinmi')) return true;
                    if (skill.includes('guxiong')) return true;
                    if (skill.includes('yongbi')) return true;
                    if (skill.includes('spyinju2')) return true;
                    if (skill.includes('beizhan2')) return true;
                    if (skill.includes('quanxue2')) return true;
                    if (skill.includes('huoxin2')) return true;
