        syr_72bian_use: {
            enable: 'phaseUse',
            usable: 1,
            position: 'he',
            filter(event, player) {
                return !player.storage.syr_72bian || player.storage.syr_72bian.length < 72;
            },
            content() {
                'step 0';
                if (!player.storage.syr_72bian) player.storage.syr_72bian = [];
                event._result = { bool: true };
                ('step 1');
                if (result.bool) {
                    var list = [];
                    var skills = [];
                    var map = [];
                    if (!_status.characterlist) {
                        lib.skill.syr_shen_pingjian.initList();
                    }
                    _status.characterlist.randomSort();
                    for (var i = 0; i < _status.characterlist.length; i++) {
                        var name = _status.characterlist[i];
                        var skills2 = lib.character[name][3];
                        for (var j = 0; j < skills2.length; j++) {
                            if (player.storage.syr_72bian.includes(skills2[j])) continue;
                            if (skills.includes(skills2[j]) || lib.skill.syr_72bian.phaseUse_special.includes(skills2[j])) {
                                list.add(name);
                                if (!map[name]) map[name] = [];
                                map[name].push(skills2[j]);
                                skills.add(skills2[j]);
                                continue;
                            }
                            var list2 = [skills2[j]];
                            game.expandSkills(list2);
                            for (var k = 0; k < list2.length; k++) {
                                var info = lib.skill[list2[k]];
                                if (!info || !info.enable || info.viewAs || info.limited || info.juexingji || info.zhuanhuanji || info.hiddenSkill || info.dutySkill) continue;
                                if (info.enable == 'phaseUse' || (Array.isArray(info.enable) && info.enable.includes('phaseUse'))) {
                                    if (info.init || info.onChooseToUse || (info.ai && (info.ai.combo || info.ai.notemp || info.ai.neg))) continue;
                                    if (info.filter) {
                                        try {
                                            var bool = info.filter(event.getParent(2), player);
                                            if (!bool) continue;
                                        } catch (e) {
                                            continue;
                                        }
                                    }
                                    list.add(name);
                                    if (!map[name]) map[name] = [];
                                    map[name].push(skills2[j]);
                                    skills.add(skills2[j]);
                                    break;
                                }
                            }
                        }
                        if (list.length > 2) break;
                    }
                    if (!skills.length) {
                        //player.draw();
                        event.finish();
                    } else {
                        //skills.unshift('摸一张牌');
                        event.list = list;
                        event.skills = skills;
                        player
                            .chooseControl(skills)
                            .set('dialog', ['请选择要发动的技能', [list, 'character']])
                            .set('ai', function () {
                                //return get.max(_status.event.controls,get.skillRank,'item');
                                return _status.event.controls.sort(function (a, b) {
                                    return get.skillRank(b, '') - get.skillRank(a, '');
                                })[0];
                            });
                    }
                } else event.finish();
                ('step 2');
                if (result.control == '摸一张牌') {
                    player.draw();
                    return;
                }
                player.storage.syr_72bian.add(result.control);
                player.addTempSkill(result.control, 'phaseUseEnd');
                player.addTempSkill('syr_72bian_temp', 'phaseUseEnd');
                player.storage.syr_72bian_temp = result.control;
                for (var i = 0; i < event.skills.length; i++)
                    if (result.control == event.skills[i]) {
                        player.flashAvatar('syr_72bian', event.list[i]);
                        player.popup(result.control);
                        game.log(player, '暂时获得了', '#b' + get.translation(event.list[i]), '的', '【' + get.skillTranslation(result.control, player) + '】');
                    }
                //event.getParent(2).goto(0);
            },
            ai: { order: 10, result: { player: 1 } },
        },
