                        for (var i = 0; i < targets.length; i++) {
                            var num = Math.max((targets[i].countCards('h') + 1) >> 1, 5);
                            if (num > 0) eff1 = Math.max(eff1, (num / 2) * get.effect(targets[i], { name: 'wuzhong' }, targets[i], player));
                            eff2 = Math.max(eff2, get.recoverEffect(targets[i], player, player));
                        }
                        if (eff1 > 0 && choices.includes('选项一') && (eff1 >= eff2 || !choices.includes('选项二'))) return '选项一';
                        if (eff2 > 0 && choices.includes('选项二')) return '选项二';
                        return 'cancel2';
