                var es = target.getCards('e', lib.filter.cardRecastable);
                if (es && es.length) target.recast(es);
                ('step 2');
                var num = target.countCards('h') - target.getHp();
                if (num > 0) target.chooseToDiscard('h', num, true);
                ('step 3');
                if (player.canCompare(target))
                    player.chooseBool(get.prompt('syr_shenji', target), '与' + get.translation(target) + '拼点').ai = function () {
                        if (player.countCards('h', 'du') == player.countCards('h') && !player.hasSkillTag('nodu') && get.effect(player, { name: 'losehp' }, player, player) < 0) return false;
                        return get.attitude(player, target) <= 0;
                    };
                ('step 4');
                if (!result.bool) event.finish();
                else {
                    var next = player.chooseToCompare(target, function (card) {
                        if (get.attitude(player, target) > 0) {
                            return 6 - get.value(card);
                        }
                        return card.number;
                    });
                    next.preserve = true;
                    next.small = get.attitude(player, target) >= 0 || target.isDamaged();
                }
                ('step 5');
                if (result.bool) {
                    var cards = [result.target];
                    if (cards.length) player.gain(cards, 'gain2');
                    target.Frbroken();
                } else {
                    player.randomDiscard();
                    player.addMark('_fr_Broken', 1, false);
                    game.log(player, '获得了1个', '#g碎玉');
                }
